// Local planning records. No account lookup or institutional verification is performed.
export const SOURCES=Object.freeze({reviewedOn:'2026-10-02',sebi:'https://www.sebi.gov.in/sebi_data/attachdocs/jun-2026/1780397706130.pdf',bank:'https://thc.nic.in/Central%20Governmental%20Rules/Banking%20Companies%20(Nomination)%20Rules,%202025.pdf',mf:'https://www.amfiindia.com/investor/become-mf-distributor?zoneName=nomination',hdfc:'https://www.hdfc.bank.in/need-help/net-banking-faqs'});
export const TYPES=['demat','bank','mf'];
export const NOMINATION=['registered','missing','unknown'];
export const REVIEW=['reported','submitted','confirmed'];
export function emptyTracker(){return {schema:2,product:'virasat',synthetic:false,accounts:[]};}
export function emptyAccount(){return {id:crypto.randomUUID(),type:'demat',institution:'',label:'',owner:'',nomineeNote:'',last4:'',nomination:'unknown',review:'reported',checkedOn:'',submittedOn:'',confirmationOn:'',recordKind:'',recordNote:'',confirmationChecked:false};}
export function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function validDate(value){if(value==='')return true;if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const date=new Date(value+'T00:00:00Z');return Number.isFinite(date.getTime())&&date.toISOString().slice(0,10)===value&&value<=today();}
export function validateAccount(value){const a=emptyAccount();if(typeof value?.id!=='string'||!/^[a-zA-Z0-9-]{1,64}$/.test(value.id))throw new Error('invalidSave');a.id=value.id;for(const [key,set] of [['type',TYPES],['nomination',NOMINATION],['review',REVIEW]]){if(!set.includes(value[key]))throw new Error('invalidSave');a[key]=value[key];}for(const key of ['institution','label','owner','nomineeNote','last4','recordNote']){if(typeof value[key]!=='string'||value[key].length>(key==='recordNote'?160:80))throw new Error('invalidSave');a[key]=value[key].trim();}if(!a.institution||!/^\d{0,4}$/.test(a.last4)||a.last4.length>0&&a.last4.length!==4)throw new Error('invalidAccount');for(const key of ['checkedOn','submittedOn','confirmationOn']){if(typeof value[key]!=='string'||!validDate(value[key]))throw new Error('invalidDate');a[key]=value[key];}if(!['','statement','registration'].includes(value.recordKind)||typeof value.confirmationChecked!=='boolean')throw new Error('invalidSave');a.recordKind=value.recordKind;a.confirmationChecked=value.confirmationChecked;
if(a.review==='submitted'&&!a.submittedOn)throw new Error('submissionRequired');
if(a.review==='confirmed'&&(a.nomination!=='registered'||!a.confirmationOn||!a.recordKind||!a.confirmationChecked))throw new Error('confirmationRequired');
if(a.review==='confirmed'&&a.submittedOn&&a.confirmationOn<a.submittedOn)throw new Error('invalidDate');
if(a.review!=='confirmed'){a.confirmationOn='';a.recordKind='';a.confirmationChecked=false;}if(a.review==='reported')a.submittedOn='';return a;}
export function validateTracker(value){if(value?.schema!==2||value.product!=='virasat'||typeof value.synthetic!=='boolean'||!Array.isArray(value.accounts)||value.accounts.length>50)throw new Error('invalidSave');const accounts=value.accounts.map(validateAccount);if(new Set(accounts.map(a=>a.id)).size!==accounts.length)throw new Error('invalidSave');return {schema:2,product:'virasat',synthetic:value.synthetic,accounts};}
export function attention(a){return a.review==='submitted'?'awaiting':a.review==='confirmed'?'confirmed':a.nomination==='missing'?'missing':a.nomination==='unknown'?'unknown':'review';}
export function orderedAccounts(accounts){const priority={missing:0,unknown:1,awaiting:2,review:3,confirmed:4};return [...accounts].sort((a,b)=>priority[attention(a)]-priority[attention(b)]);}
export function counts(c){return {total:c.accounts.length,missing:c.accounts.filter(a=>attention(a)==='missing').length,unknown:c.accounts.filter(a=>attention(a)==='unknown').length,awaiting:c.accounts.filter(a=>attention(a)==='awaiting').length,confirmed:c.accounts.filter(a=>attention(a)==='confirmed').length};}
export function sampleTracker(){const c=emptyTracker();c.synthetic=true;const a=emptyAccount();a.id='demo-demat';a.type='demat';a.institution='Example Securities';a.owner='Parent';a.label='Long-term shares';a.nomination='missing';a.checkedOn=today();const b=emptyAccount();b.id='demo-bank';b.type='bank';b.institution='Example Bank';b.owner='Me';b.label='Savings';b.nomination='registered';const m=emptyAccount();m.id='demo-mf';m.type='mf';m.institution='Example Mutual Fund';m.owner='Parent';m.label='Family folio';c.accounts=[a,b,m];return c;}
export function familySummary(c){return {format:'virasat-family-summary',version:1,synthetic:c.synthetic,generatedAt:new Date().toISOString(),accounts:c.accounts.map(({id,recordNote,confirmationChecked,...a})=>({...a,evidenceBasis:a.review==='confirmed'?'User reports reviewing an institution record showing registration':a.review==='submitted'?'User reports sending a request; registration not confirmed':'User report only'})),sources:SOURCES,limitations:['This is a local family planning list, not an institutional account register or a nomination request.','No account discovery, automatic verification, institution submission or succession determination.','Receipt of a request is separate from registration. Confirm with each institution.','Summary contains institution labels, family/nominee nicknames and last four digits when supplied; free-text record notes are omitted.']};}
